import React from 'react';
import { Button, DropdownMenu, useToaster } from '@gravity-ui/uikit';
import { Copy, Pencil, Share, TrashBin } from '@gravity-ui/icons';

export function App() {
  const { add } = useToaster();

  const handleAction = (name: string) => () => {
    add({
      name: `action-${name}`,
      title: `Действие: ${name}`,
    });
  };

  return (
    <div style={{ padding: 24 }}>
      <DropdownMenu
        size="m"
        items={[
          {
            text: 'Редактировать',
            iconStart: <Pencil />,
            action: handleAction('Редактировать'),
          },
          {
            text: 'Скопировать',
            iconStart: <Copy />,
            action: handleAction('Скопировать'),
          },
          {
            text: 'Поделиться',
            iconStart: <Share />,
            action: handleAction('Поделиться'),
          },
          {
            text: 'Удалить',
            iconStart: <TrashBin />,
            theme: 'danger',
            action: handleAction('Удалить'),
          },
        ]}
        renderSwitcher={(props) => (
          <Button {...props} view="outlined">
            Действия
          </Button>
        )}
      />
    </div>
  );
}

